#!/usr/bin/env node
/**
 * Emit the runtime operation index this server's declaration layer reads.
 *
 * ── Why a generated file and not a JSON import ──────────────────────────────
 * `src/generated/endpoints-types.ts` is `openapi-typescript` output: types only,
 * erased at runtime. `defineTools()` (packages/mcp-core/src/declare-tools.ts)
 * derives a tool's schema and its validation rules from the OpenAPI operation,
 * so it needs those facts as DATA, not as types. `buildOperationIndex()` distils
 * the 1.0 MB spec down to the ~95 KB of route/verb/parameter/body facts a schema
 * is built from; `serializeOperationIndex()` is the shipping form.
 *
 * The spec itself lives at ../openapi-specs/26R1/, outside this package, so it
 * cannot be imported at runtime. This script freezes it into the package at
 * development time instead.
 *
 *     npm run generate       # regenerates types AND this index
 *
 * The index is checked in, so a clone builds without the spec directory. A test
 * (`src/__tests__/operation-index.test.ts`) asserts the checked-in file is
 * byte-identical to a fresh run, so it cannot drift from the spec silently.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import { buildOperationIndex, serializeOperationIndex } from "@bconnect/mcp-core";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..", "..");

export const SPEC_PATH = join(repoRoot, "openapi-specs", "26R1", "bConnect_Endpoints.json");
export const OUTPUT_PATH = join(here, "..", "src", "generated", "endpoints-operation-index.ts");

/** The file body, so the drift test can compare without writing anything. */
export function renderOperationIndexModule() {
  const spec = JSON.parse(readFileSync(SPEC_PATH, "utf8"));
  const index = buildOperationIndex(spec, "endpoints");
  const json = serializeOperationIndex(index);

  return [
    "/**",
    " * GENERATED by scripts/generate-operation-index.mjs — do not edit.",
    " *",
    ` * Source: openapi-specs/26R1/bConnect_Endpoints.json (${Object.keys(index.operations).length} operations).`,
    " *",
    " * The runtime half of the generated layer: `endpoints-types.ts` gives the",
    " * compiler the shapes, this gives `defineTools()` the same facts at runtime.",
    " * 26R1 only — see README. Regenerate with `npm run generate`.",
    " */",
    "",
    'import { deserializeOperationIndex, type OperationIndex } from "@bconnect/mcp-core";',
    "",
    "const SERIALIZED = " + JSON.stringify(json) + ";",
    "",
    "/** Every operation bConnect_Endpoints.json declares, distilled. */",
    "export const ENDPOINTS_OPERATIONS: OperationIndex = deserializeOperationIndex(SERIALIZED);",
    "",
  ].join("\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const body = renderOperationIndexModule();
  writeFileSync(OUTPUT_PATH, body, "utf8");
  console.error(`generate-operation-index: wrote ${OUTPUT_PATH} (${body.length} B)`);
}
